import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Le Carnaval","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/bal/index.md","filePath":"gitbook/bal/index.md"}'),r={name:"gitbook/bal/index.md"};function o(i,e,l,u,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="le-carnaval" tabindex="-1">Le Carnaval <a class="header-anchor" href="#le-carnaval" aria-label="Permalink to &quot;Le Carnaval&quot;">​</a></h1><blockquote><p>Un bal masqué où chacun cache bien plus que son visage.</p></blockquote><h2 id="l-histoire" tabindex="-1">L&#39;histoire <a class="header-anchor" href="#l-histoire" aria-label="Permalink to &quot;L&#39;histoire&quot;">​</a></h2><p>Le Carnaval des Morts est un bal maudit qui se tient chaque année dans la ville oubliée de <strong>Villeperdue</strong>. Les invités portent des masques qui leur confèrent des identités et des pouvoirs. Mais une malédiction plane sur le bal : chaque nuit, des masques se brisent, révélant ceux qui se cachent derrière.</p><h2 id="l-ambiance" tabindex="-1">L&#39;ambiance <a class="header-anchor" href="#l-ambiance" aria-label="Permalink to &quot;L&#39;ambiance&quot;">​</a></h2><p>Le Carnaval est un lieu de <strong>mystère</strong>, de <strong>trahison</strong> et de <strong>survie</strong>. Les salons vocaux sont les trois zones du bal :</p><table tabindex="0"><thead><tr><th>Salon</th><th>Ambiance</th></tr></thead><tbody><tr><td><strong>La Grande Tente</strong></td><td>Le cœur du bal. Lumineux, bruyant, central.</td></tr><tr><td><strong>La Foire aux Monstres</strong></td><td>Les attractions sombres. Loin des regards.</td></tr><tr><td><strong>Le Cimetière des Caravanes</strong></td><td>Les tombes des anciens carnavals. Glacial, isolé.</td></tr></tbody></table><h2 id="le-personnel" tabindex="-1">Le personnel <a class="header-anchor" href="#le-personnel" aria-label="Permalink to &quot;Le personnel&quot;">​</a></h2><ul><li><strong>L&#39;Hôte du Carnaval</strong> : le narrateur, celui qui fait vivre l&#39;ambiance du bal. Il arbitre les situations ambiguës.</li><li><strong>Les Invités</strong> : les joueurs. Certains sont des <strong>Vivants</strong>, d&#39;autres des <strong>Revenants</strong>. Personne ne sait qui est qui.</li><li><strong>Les Masques</strong> : chaque masque a un lore, des PV, une attaque de combat, des capacités jour/nuit et un passif.</li></ul><h2 id="le-deroulement" tabindex="-1">Le déroulement <a class="header-anchor" href="#le-deroulement" aria-label="Permalink to &quot;Le déroulement&quot;">​</a></h2><p>Le Carnaval suit un cycle répété :</p><blockquote><p><strong>Nuit</strong> → <strong>Résolution</strong> → <strong>Débats</strong> → <strong>Actions de Jour</strong> → <strong>Duels</strong> → <em>(cycle suivant)</em></p></blockquote><p>Pendant la <strong>Nuit</strong>, les masques se dévoilent et les capacités secrètes se déclenchent. Pendant les <strong>Débats</strong>, les joueurs discutent, accusent et défendent. Pendant les <strong>Duels</strong>, les joueurs s&#39;affrontent directement.</p><h2 id="ce-qui-rend-le-carnaval-unique" tabindex="-1">Ce qui rend le Carnaval unique <a class="header-anchor" href="#ce-qui-rend-le-carnaval-unique" aria-label="Permalink to &quot;Ce qui rend le Carnaval unique&quot;">​</a></h2><ul><li><strong>Les PV secrets</strong> : les joueurs connaissent leurs propres PV mais pas ceux des autres.</li><li><strong>Les masques</strong> : chaque masque a des capacités uniques et un passif qui change la stratégie.</li><li><strong>Les Revenants aléatoires</strong> : les camps sont tirés au sort, pas choisis.</li><li><strong>Les zones vocales</strong> : les joueurs se déplacent entre 3 salons. Certains masques vérifient leur position.</li><li><strong>Les rumeurs</strong> : un joueur K.O. peut laisser un dernier message — une rumeur qui peut contenir des indices ou des mensonges.</li></ul><h2 id="theme" tabindex="-1">Thème <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Thème&quot;">​</a></h2><p>Le jeu s&#39;inspire du folklore des carnavals macabres. Les masques sont des créatures fantastiques — pas des Pokémon — et le ton est sombre mais festif. L&#39;Hôte du Carnaval est le narrateur, celui qui fait vivre l&#39;ambiance du bal.</p>',17)])])}const g=a(r,[["render",o]]);export{m as __pageData,g as default};
